-- Preserve customised Care Assistant permissions when adopting Support Worker.
UPDATE AccessLevel old LEFT JOIN AccessLevel current ON current.name='Support Worker' SET old.name='Support Worker' WHERE old.name='Care Assistant' AND current.id IS NULL;
