-- Exact/case-insensitive matches and the former Care Assistant label only.
UPDATE StaffMember s JOIN AccessLevel a ON LOWER(a.name)=CASE WHEN LOWER(TRIM(s.jobRole))='care assistant' THEN 'support worker' ELSE LOWER(TRIM(s.jobRole)) END SET s.jobRole=a.name,s.accessLevelId=a.id WHERE a.name IN ('Administrator','Assistant Manager','Manager','Team Leader','Support Worker');
-- Apply the selected grade to accounts already linked to these staff records.
UPDATE User u JOIN StaffMember s ON s.userId=u.id JOIN AccessLevel a ON a.id=s.accessLevelId SET u.accessLevelId=a.id,u.role=a.baseRole,u.permissionOverrides=a.permissions WHERE a.name IN ('Administrator','Assistant Manager','Manager','Team Leader','Support Worker');
DELETE se FROM Session se JOIN StaffMember s ON s.userId=se.userId JOIN AccessLevel a ON a.id=s.accessLevelId WHERE a.name IN ('Administrator','Assistant Manager','Manager','Team Leader','Support Worker');
DELETE se FROM StaffPortalSession se JOIN StaffMember s ON s.id=se.accountId JOIN AccessLevel a ON a.id=s.accessLevelId WHERE a.name IN ('Administrator','Assistant Manager','Manager','Team Leader','Support Worker');
